type Category =
  | "Logic & Knowledge"
  | "Mathematical Reasoning"
  | "Probability & Strategy"
  | "Algorithms & Optimization"
  | "Spatial Reasoning"
  | "Patterns & Numbers";

type PuzzleSeed = {
  id: string;
  title: string;
  category: Category;
  difficulty: number;
  time: number;
  question: string;
  options: string[];
  correctOption: number;
  hints: [string, string, string];
  explanation: string;
  takeaway: string;
  method: string;
};

function puzzle(seed: PuzzleSeed) {
  return {
    ...seed,
    explanation: `${seed.explanation} Work slowly from the rule that cannot change, then check the other choices against it. That small check is what turns a clever guess into a reliable solution.`,
    verification: { method: seed.method, reviewed: true, version: 2 },
  };
}

